glm::vec3 r = pi->position - pj->position;
float rSquared = glm::dot(r, r);
if (rSquared < h2) {
    float rSquaredInv = 1.0f / rSquared;
    float rSquaredInv3 = rSquaredInv * rSquaredInv * rSquaredInv;
    float rSquaredInv4 = rSquaredInv3 * rSquaredInv;
    float poly6 = 315.0f / (64.0f * PI * std::pow(settings.h, 9)) * rSquaredInv4;
    density += massPoly6 * poly6;
}

